code.source:
#include <iostream>
#include <string>
using namespace std;

class Animal {
public:
    string name = "Moti";
    void eat() const { cout << name << " eats" << endl; }
};

class Dog : public Animal {
public:
    void fetch() const { cout << name << " fetches" << endl; }
};

int main() {
    Dog d;
    d.eat();
    d.fetch();
    return 0;
}

#include <iostream>
using namespace std;

class Animal {
public:
    void speak() const { cout << "..." << endl; }
};

class Dog : public Animal {
public:
    void speak() const { cout << "Woof" << endl; }
};

int main() {
    Dog d;
    d.speak();
    d.Animal::speak();
    return 0;
}

